// Sink is the server the stack is built on: the generated CRUD servers,
// with a List on every entity that declared one.
//
// A list belongs here and not in a layer in front for the reason the wall
// does: it is the read the generated servers do not make, so nothing else
// narrows it -- and a list cut short at a limit and filtered afterwards is
// one that any tenant can push another's rows out of by making enough of
// its own.
//
//	sink, err := pd.NewSink(db, bare.WithMinter(pd.Minter()), bare.WithScope(pd.Wall()))
type Sink struct {
	bare.Server

	// w is what a Watch listens on, and is nil for a deployment that
	// serves none. It is here rather than on the generated Store because
	// that struct is the ORM generator's and knows nothing about payday.
	w *watch.Watch

	// namer decides the alias of a row being added, and nil is
	// `slug.Names`: fold what was given, make one up when nothing was.
	// See [Sink.WithNamer].
	namer slug.Namer

	// joined says this server was put on somebody else's transaction, and
	// is set by [Sink.WithDriver] because that is the only way it happens.
	//
	// What it is read for is the retry in Add and AddMany. A constraint
	// violation ends the transaction it happened in -- PostgreSQL refuses
	// everything after one until it is rolled back -- so a second attempt
	// inside a transaction this server did not open would fail for a reason
	// that has nothing to do with names, and would take the caller's other
	// writes with it.
	joined bool
}

func NewSink(db *ent.Client, opts ...bare.Option) (Sink, error) {
	// Before anything is built on it. What this refuses is a binary whose
	// payday is not the one that wrote this file, which is a thing that
	// compiles and serves and is wrong; see [Check].
	if err := Check(); err != nil {
		return Sink{}, err
	}

	v, err := bare.NewServer(db, opts...)
	if err != nil {
		return Sink{}, err
	}

	return Sink{Server: v}, nil
}

// WithWatch answers with this server publishing to `w`, which is what a
// Watch reads from. A server built without one serves no Watch.
func (s Sink) WithWatch(w *watch.Watch) Sink {
	s.w = w
	return s
}

// WithNamer answers with this server deciding aliases with `n`.
//
// It is the fourth of the hooks the generated servers converge on --
// `bare.Minter` decides the key, `bare.Recorder` is told about the write,
// `bare.Scope` narrows the read, and this decides the name. It is payday's
// rather than the ORM generator's because an alias is payday's idea: it is
// what a slug resolves against, and nothing in `orm` has a word for it.
//
// Unset is `slug.Names`: fold what was given, and make a name up when
// nothing was. An app whose rows have to be named says so here, where a
// reader finds it:
//
//	sink = sink.WithNamer(slug.RequiredFor(nil, "payday.Tenant", "app.Project"))
func (s Sink) WithNamer(n slug.Namer) Sink {
	s.namer = n
	return s
}

var _ rstr.Server = Sink{}
var _ enttx.Binder[rstr.Server] = Sink{}

// WithDriver answers with this server running on `drv`; see [Gate.WithDriver].
func (s Sink) WithDriver(drv dialect.Driver) (rstr.Server, error) {
	v, err := s.Server.WithDriver(drv)
	if err != nil {
		return nil, err
	}

	// Everything this Sink was told, carried across. A field left out here
	// is a rule the requests inside a transaction go around, and it fails
	// only there -- which is the hardest place to notice it.
	return Sink{Server: v.(bare.Server), w: s.w, namer: s.namer, joined: true}, nil
}

type sinkAccess struct {
	rstr.AccessServiceServer
	store  bare.Store
	w      *watch.Watch
	namer  slug.Namer
	joined bool
}

func (s Sink) Access() rstr.AccessServiceServer {
	return sinkAccess{s.Server.Access(), s.Server.Store, s.w, s.namer, s.joined}
}

// orderAccess is how Accesss come back.
//
// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderAccess = []sqlpage.Order{
	{Column: access.FieldDateCreated, Desc: true},
	{Column: access.FieldId, Desc: true},
}

func afterAccess(v string, by []sqlpage.Order, tag string) (func(*sql.Selector), error) {
	var (
		at0 time.Time
		at1 uuid.UUID
	)
	if err := pdAfter(v, tag, &at0, &at1); err != nil {
		return nil, err
	}

	return sqlpage.After(by, []any{at0, at1})
}

func nextAccess(last *ent.Access, tag string) (string, error) {
	return pdNext(tag, last.DateCreated, last.Id)
}

// orderByAccess is an order as ent orders a query by it.
func orderByAccess(by []sqlpage.Order) []access.OrderOption {
	out := make([]access.OrderOption, len(by))
	for i, o := range by {
		if o.Desc {
			out[i] = sql.OrderByField(o.Column, sql.OrderDesc()).ToFunc()
			continue
		}

		out[i] = sql.OrderByField(o.Column).ToFunc()
	}

	return out
}

const (
	// AccessPageSize is what a request that did not say gets, and
	// AccessPageLimit is the most it gets however loudly it asks.
	AccessPageSize  = 50
	AccessPageLimit = 200

	// AccessFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	AccessFilterLimit = 32
)

// List answers with the Accesss that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkAccess) List(ctx context.Context, req *rstr.AccessListRequest) (*rstr.AccessListResponse, error) {
	q := s.store.Db.Access.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.AccessNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > AccessFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), AccessFilterLimit)
		}

		ps := make([]predicate.Access, 0, len(fs))
		for i, f := range fs {
			p, err := filterAccess(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(access.Or(ps...))
	}

	// Which order, and which way: one the schema declared, and never one a
	// request makes up, since an order is a walk of an index.
	by, after, next, tag := orderAccess, afterAccess, nextAccess, ""
	if req.GetReverse() {
		// The same index, walked from the other end.
		by, tag = pdReverse(by), tag+"/reverse"
	}

	if v := req.GetAfter(); v != "" {
		p, err := after(v, by, tag)
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), AccessPageSize, AccessPageLimit)
	us, err := q.Order(orderByAccess(by)...).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*rstr.Access, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := rstr.AccessListResponse_builder{Items: items}.Build()
	if more {
		v, err := next(us[len(us)-1], tag)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(v)
	}

	return res, nil
}

// filterAccess turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterAccess(f *rstr.AccessFilter) (predicate.Access, error) {
	ps := make([]predicate.Access, 0, 1)
	if f.HasActorId() {
		k, err := entuuid.FromBytes(f.GetActorId())
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "actor_id: %s", err)
		}

		ps = append(ps, access.ActorIdEQ(k))
	}
	if f.HasTenantId() {
		k, err := entuuid.FromBytes(f.GetTenantId())
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "tenant_id: %s", err)
		}

		ps = append(ps, access.TenantIdEQ(k))
	}
	if f.HasActorTenantId() {
		k, err := entuuid.FromBytes(f.GetActorTenantId())
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "actor_tenant_id: %s", err)
		}

		ps = append(ps, access.ActorTenantIdEQ(k))
	}
	if f.HasKind() {
		ps = append(ps, access.KindEQ(f.GetKind()))
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return access.And(ps...), nil
}

type sinkApiKey struct {
	rstr.ApiKeyServiceServer
	store  bare.Store
	w      *watch.Watch
	namer  slug.Namer
	joined bool
}

func (s Sink) ApiKey() rstr.ApiKeyServiceServer {
	v := sinkApiKey{s.Server.ApiKey(), s.Server.Store, s.w, s.namer, s.joined}
	v.ApiKeyServiceServer = bare.ApiKeyWithAddRule(v.ApiKeyServiceServer, v.admit)
	return v
}

// admit decides the name of a row an Add of ApiKey writes, refusing one
// that was given and cannot be one.
//
// It is asked of an Add and of every item of an AddMany; see [Sink.ApiKey].
//
// The name goes through [Sink.WithNamer], which is unset in most
// deployments and then means: fold what was given, and make a name up
// when nothing was -- for the reason `bare.Minter` makes a key up. An app
// whose rows have to be named says so with `slug.Required`; see
// `slug.Names` for why that is the way round it is.
func (s sinkApiKey) admit(ctx context.Context, req *rstr.ApiKeyAddRequest) (*rstr.ApiKeyAddRequest, error) {
	// Copied rather than written to: the request belongs to whoever called,
	// and for a call made in this process that is a message they may still
	// be holding -- a server that changed a caller's own field would be
	// changing a value they can read back.
	r := proto.CloneOf(req)

	v, err := slug.NameWith(ctx, s.namer, "roster.ApiKey", req.GetAlias(), req)
	if err != nil {
		return nil, pderr.At("alias", err)
	}
	r.SetAlias(v)

	return r, nil
}

// Add tries again when the name it made up was taken.
//
// The name is [sinkApiKey.admit]'s, and every try goes through it, so a
// name made up is made up again and a name given is the same each time.
func (s sinkApiKey) Add(ctx context.Context, req *rstr.ApiKeyAddRequest) (*rstr.ApiKey, error) {
	// How many names to try. More than one only when the caller named
	// nothing -- then the name is this server's and a collision is this
	// server's to resolve. A name the caller gave is theirs, and quietly
	// choosing a different one would write a row they did not ask for.
	//
	// And only when this Add opens its own transaction; see [Sink.joined].
	tries := 1
	if req.GetAlias() == "" && !s.joined {
		tries = slug.Tries
	}

	for try := 0; ; try++ {
		res, err := s.ApiKeyServiceServer.Add(ctx, req)
		if err == nil || try+1 >= tries || status.Code(err) != codes.AlreadyExists {
			// Whatever it was, said in the words it was said in. Rewriting
			// it into "no free name" would assert the one thing this cannot
			// know -- a duplicate key is the same code -- and would say it
			// loudest exactly when it is wrong.
			return res, err
		}
	}
}

// Patch folds a name it was given, and says nothing about one it was not.
//
// The presence is the whole of the difference from [sinkApiKey.Add]: a patch
// that does not mention the alias is not a patch setting it to the empty
// string, and refusing one would make every patch of any other field carry
// the name along.
//
// The namer is **not** asked here, and that is the second difference. It
// decides the name of a row being made; a patch that cleared the alias is
// a caller asking for something invalid, and answering that with an
// invented name would hand them a row they did not ask for.
func (s sinkApiKey) Patch(ctx context.Context, req *rstr.ApiKeyPatchRequest) (*rstr.ApiKey, error) {
	if !req.HasAlias() {
		return s.ApiKeyServiceServer.Patch(ctx, req)
	}

	v, err := slug.ParseAlias(req.GetAlias())
	if err != nil {
		return nil, pderr.At("alias", err)
	}

	req = proto.CloneOf(req)
	req.SetAlias(v)

	return s.ApiKeyServiceServer.Patch(ctx, req)
}

// orderApiKey is how ApiKeys come back.
//
// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderApiKey = []sqlpage.Order{
	{Column: apikey.FieldDateCreated, Desc: false},
	{Column: apikey.FieldId, Desc: false},
}

func afterApiKey(v string, by []sqlpage.Order, tag string) (func(*sql.Selector), error) {
	var (
		at0 time.Time
		at1 uuid.UUID
	)
	if err := pdAfter(v, tag, &at0, &at1); err != nil {
		return nil, err
	}

	return sqlpage.After(by, []any{at0, at1})
}

func nextApiKey(last *ent.ApiKey, tag string) (string, error) {
	return pdNext(tag, last.DateCreated, last.Id)
}

// orderByApiKey is an order as ent orders a query by it.
func orderByApiKey(by []sqlpage.Order) []apikey.OrderOption {
	out := make([]apikey.OrderOption, len(by))
	for i, o := range by {
		if o.Desc {
			out[i] = sql.OrderByField(o.Column, sql.OrderDesc()).ToFunc()
			continue
		}

		out[i] = sql.OrderByField(o.Column).ToFunc()
	}

	return out
}

const (
	// ApiKeyPageSize is what a request that did not say gets, and
	// ApiKeyPageLimit is the most it gets however loudly it asks.
	ApiKeyPageSize  = 20
	ApiKeyPageLimit = 100

	// ApiKeyFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	ApiKeyFilterLimit = 32
)

// List answers with the ApiKeys that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkApiKey) List(ctx context.Context, req *rstr.ApiKeyListRequest) (*rstr.ApiKeyListResponse, error) {
	q := s.store.Db.ApiKey.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.ApiKeyNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > ApiKeyFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), ApiKeyFilterLimit)
		}

		ps := make([]predicate.ApiKey, 0, len(fs))
		for i, f := range fs {
			p, err := filterApiKey(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(apikey.Or(ps...))
	}

	// Which order, and which way: one the schema declared, and never one a
	// request makes up, since an order is a walk of an index.
	by, after, next, tag := orderApiKey, afterApiKey, nextApiKey, ""
	if req.GetReverse() {
		// The same index, walked from the other end.
		by, tag = pdReverse(by), tag+"/reverse"
	}

	if v := req.GetAfter(); v != "" {
		p, err := after(v, by, tag)
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), ApiKeyPageSize, ApiKeyPageLimit)
	us, err := q.Order(orderByApiKey(by)...).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*rstr.ApiKey, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := rstr.ApiKeyListResponse_builder{Items: items}.Build()
	if more {
		v, err := next(us[len(us)-1], tag)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(v)
	}

	return res, nil
}

// filterApiKey turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterApiKey(f *rstr.ApiKeyFilter) (predicate.ApiKey, error) {
	ps := make([]predicate.ApiKey, 0, 1)
	if f.HasRef() {
		p, err := bare.ApiKeyPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasHolder() {
		w := f.GetHolder()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "holder: %s", err)
			}

			ps = append(ps, apikey.HolderIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.HolderPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, apikey.HasHolderWith(q))
		}
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return apikey.And(ps...), nil
}

