// Audit is the layer that refuses a trail row written by hand.
//
// The Rpcs exist because the trail is an entity like any other and a test is
// far plainer for having them. A deployment serves none of the ones that
// write: a trail somebody can edit is evidence of nothing.
type Audit struct {
	rstr.Overlay
}

func NewAudit(next rstr.Server) Audit {
	return Audit{rstr.NewOverlay(next)}
}

var _ rstr.Server = Audit{}
var _ enttx.Binder[rstr.Server] = Audit{}

// WithDriver answers with this stack running on `drv`; see [Gate.WithDriver].
func (s Audit) WithDriver(drv dialect.Driver) (rstr.Server, error) {
	next, err := enttx.Rebind(s.Next(), drv)
	if err != nil {
		return nil, err
	}

	return NewAudit(next), nil
}

// AuditBuild makes a builder of this layer so that it can be stacked.
func AuditBuild() rstr.Builder { return auditBuilder{} }

type auditBuilder struct{}

func (auditBuilder) Build(next rstr.Server) (rstr.Server, error) {
	return NewAudit(next), nil
}

type auditService struct {
	Audit
	rstr.AuditServiceServer
}

func (s Audit) Audit() rstr.AuditServiceServer {
	return auditService{s, s.Next().Audit()}
}

func (s auditService) Add(ctx context.Context, req *rstr.AuditAddRequest) (*rstr.Audit, error) {
	return nil, errTrail()
}

func (s auditService) Patch(ctx context.Context, req *rstr.AuditPatchRequest) (*rstr.Audit, error) {
	return nil, errTrail()
}

func (s auditService) Apply(ctx context.Context, req *rstr.AuditApplyRequest) (*rstr.Audit, error) {
	return nil, errTrail()
}

func (s auditService) Erase(ctx context.Context, req *rstr.AuditRef) (*rstr.AuditEraseResponse, error) {
	return nil, errTrail()
}

// errTrail is Unimplemented and not PermissionDenied, and to everybody: it
// is not about who is asking, and no credential changes it.
func errTrail() error {
	return status.Error(codes.Unimplemented,
		"the trail is written by what happened, not by anybody asking")
}

// Recorder writes one row of the trail for every write the generated
// servers make, keeping as much of each as `content` says of its kind.
//
// It is not a layer and it does not override an Rpc. The servers call it
// from inside the transaction that makes the write, so the row and the
// record of it hold or fall together -- and so every Rpc that changes
// anything is on the trail without anybody having listed them.
//
//	content, err := c.Audit.Contents()
//	sink, err := bare.NewServer(db, bare.WithRecorder(pd.Recorder(content)))
//
// The content is asked for rather than defaulted, so that a deployment's
// `audit.content` is not something an app can configure and then forget to
// hand over: the zero value is the default, and passing it says so.
func Recorder(content audit1.Contents) bare.Recorder { return recorder{content} }

type recorder struct{ content audit1.Contents }

var _ bare.SnapshotRecorder = recorder{}

// Snapshots asks for the row each write leaves, which is what a line of the
// trail holds. The write has it already: an Add's INSERT reads it back, in
// the same statement where the dialect has RETURNING, and a Patch or an
// Apply reads it back to answer with. So Record reads it again only for an
// Erase, which hands none over.
func (recorder) Snapshots(string) bare.SnapshotOptions {
	return bare.SnapshotOptions{Value: true}
}

// Record writes what happened. It runs inside the write's transaction, so an
// error here takes the write with it -- which is the answer wanted: a write
// that could not be accounted for did not happen.
//
// It writes through the server it was handed, which runs on that transaction
// and does not record; a recorder that recorded its own writes would not
// stop.
func (r recorder) Record(ctx context.Context, s bare.Server, c bare.Change) error {
	// Which entity this is about, before anything decides what of the
	// write may be kept: a field declared `secret:` or `personal:` belongs
	// to one entity, and the identifier's domain byte is the only thing
	// that says which.
	key, err := audit1.Identifier(c.Key)
	if err != nil {
		return err
	}

	level := r.content.Of(key.Domain())
	md, secret, personal := described(key)

	// What the write said: the document it was compiled from, and for an
	// Add, which was compiled from none, the row it made as a patch from
	// the empty row.
	doc := c.Patch
	if doc == nil && c.Value != nil && added(c.By) {
		if doc, err = audit1.Created(c.Value); err != nil {
			return status.Errorf(codes.Internal, "the trail of %s: %s", c.Method, err)
		}
	}
	fields := []uint32{}
	if md != nil {
		fields = audit1.FieldsOf(doc, md)
	}

	// A keyed digest of the row the write left, when the deployment keeps
	// them: of the row it handed over, without what the entity declared
	// `secret:` or `personal:`, and over the fields this build knows.
	digest, covered := []byte{}, []uint32{}
	if d := r.content.Digest; d != nil && c.Value != nil && md != nil {
		row := proto.Clone(c.Value)
		audit1.Clear(row, secret)
		audit1.Clear(row, personal)
		covered = audit1.Covered(md, slices.Concat(secret, personal))
		if digest, err = d.Of(key, row, covered); err != nil {
			return status.Errorf(codes.Internal, "the trail of %s: %s", c.Method, err)
		}
	}

	var patch proto.Message
	if level != audit1.ContentFields {
		if v := audit1.Withhold(doc, slices.Concat(secret, personal)); v != nil {
			patch = v
		}
	}

	v, err := audit1.Of(ctx, c.Method, c.Key, patch)
	if err != nil {
		return err
	}

	// The row this happened to, which is where the object's tenant and the
	// state after the write both come from: the one the write handed over,
	// or read when it handed none. Absent for an Erase that took the row
	// with it; see [subject].
	tenant, value, err := subject(ctx, s, v.Object, c.Value, level == audit1.ContentValue)
	if err != nil {
		return err
	}
	if tenant == uuid.Nil() {
		// Nothing to file it under but the actor's own, which is what the
		// trail said for every row before this. It is the honest fallback
		// rather than a zero: a record nobody can read is not a record.
		tenant = uuid.UUID(v.Tenant)
	}

	domain := uint32(v.Object.Domain())

	// Kept for the commit, when the transaction keeps anything: written
	// there with the rest of what it recorded, a statement for every few
	// hundred rows rather than one each. The row is decided here, as the
	// one below is -- its key, the moment it was recorded -- and only the
	// writing waits. See [keptTrail].
	if k, ok := dialect.KeepOf(s.Store.Db.Driver()); ok {
		q := s.Store.Db.Audit.Create().
			SetId(uuid.New()).
			SetTenantId(tenant).
			SetActorTenantId(uuid.UUID(v.Tenant)).
			SetActorId(uuid.UUID(v.Actor)).
			SetTraceId(notNull(v.Trace)).
			SetAction(v.Action).
			SetObjectId(uuid.UUID(v.Object)).
			SetDomain(domain).
			SetPatch(notNull(v.Patch)).
			SetValue(notNull(value)).
			SetFields(fields).
			SetDigest(digest).
			SetDigestFields(covered).
			SetDateCreated(time.Now().UTC())
		if !v.Counterpart.IsZero() {
			q.SetCounterpartTenantId(uuid.UUID(v.Counterpart))
		}

		return keptTrailOf(k, s.Store.Db).add(ctx, q)
	}

	_, err = s.Audit().Add(ctx, rstr.AuditAddRequest_builder{
		TenantId:            tenant[:],
		ActorTenantId:       v.Tenant.Bytes(),
		ActorId:             v.Actor.Bytes(),
		TraceId:             notNull(v.Trace),
		Action:              v.Action,
		ObjectId:            v.Object.Bytes(),
		Domain:              &domain,
		Patch:               notNull(v.Patch),
		Value:               notNull(value),
		Fields:              fields,
		Digest:              digest,
		DigestFields:        covered,
		CounterpartTenantId: v.CounterpartBytes(),
	}.Build())

	return err
}

// notNull is `v` as a column that says it always has bytes takes it.
//
// The two drivers disagree about exactly one value: a nil `[]byte` is Sql
// NULL to pgx and an empty blob to SQLite's driver. So a nil bound to a NOT
// NULL column is a write that passes on the database the tests run on and is
// refused by the one the app is deployed on.
//
// Nothing is hidden by it. These columns are NOT NULL, so there is no nil for
// them to mean: an empty `trace_id` is a call nobody traced, an empty `patch`
// is a write that was not compiled from a document, an empty `value` is a row
// that was not there to read. `counterpart_tenant_id` is nullable so that nil
// can say there was no other party, and it does not come through here.
func notNull(v []byte) []byte {
	if v == nil {
		return []byte{}
	}

	return v
}

// described is the message the rows of `key`'s entity are, and the fields of
// it a row of the trail holds no value of: the ones it declared `secret`,
// which nothing answers with, and the ones it declared `personal`, which the
// trail records the setting of and not the value (#92). Nil for a domain
// this app does not have.
//
// Which entity it is comes from the identifier, as everywhere else here: a
// `pdid` carries its domain, so one switch answers it for every entity
// there will ever be.
func described(key pdid.Id) (protoreflect.MessageDescriptor, []protoreflect.FieldDescriptor, []protoreflect.FieldDescriptor) {
	switch key.Domain() {
	case AccessDomain:
		return describedAccess.md, describedAccess.secret, describedAccess.personal
	case ApiKeyDomain:
		return describedApiKey.md, describedApiKey.secret, describedApiKey.personal
	case ArchivedDomain:
		return describedArchived.md, describedArchived.secret, describedArchived.personal
	case AuditDomain:
		return describedAudit.md, describedAudit.secret, describedAudit.personal
	case BindingDomain:
		return describedBinding.md, describedBinding.secret, describedBinding.personal
	case ConnectionDomain:
		return describedConnection.md, describedConnection.secret, describedConnection.personal
	case ContinuationDomain:
		return describedContinuation.md, describedContinuation.secret, describedContinuation.personal
	case CredentialDomain:
		return describedCredential.md, describedCredential.secret, describedCredential.personal
	case DelegationDomain:
		return describedDelegation.md, describedDelegation.secret, describedDelegation.personal
	case EmailDomain:
		return describedEmail.md, describedEmail.secret, describedEmail.personal
	case GroupDomain:
		return describedGroup.md, describedGroup.secret, describedGroup.personal
	case GroupExposureDomain:
		return describedGroupExposure.md, describedGroupExposure.secret, describedGroupExposure.personal
	case GroupMembershipDomain:
		return describedGroupMembership.md, describedGroupMembership.secret, describedGroupMembership.personal
	case HolderDomain:
		return describedHolder.md, describedHolder.secret, describedHolder.personal
	case HostDomain:
		return describedHost.md, describedHost.secret, describedHost.personal
	case HostProofDomain:
		return describedHostProof.md, describedHostProof.secret, describedHostProof.personal
	case IdentityDomain:
		return describedIdentity.md, describedIdentity.secret, describedIdentity.personal
	case LinkDomain:
		return describedLink.md, describedLink.secret, describedLink.personal
	case MailDomainDomain:
		return describedMailDomain.md, describedMailDomain.secret, describedMailDomain.personal
	case NominationDomain:
		return describedNomination.md, describedNomination.secret, describedNomination.personal
	case OutboxDomain:
		return describedOutbox.md, describedOutbox.secret, describedOutbox.personal
	case RoleDomain:
		return describedRole.md, describedRole.secret, describedRole.personal
	case SessionDomain:
		return describedSession.md, describedSession.secret, describedSession.personal
	case SiteDomain:
		return describedSite.md, describedSite.secret, describedSite.personal
	case SiteMembershipDomain:
		return describedSiteMembership.md, describedSiteMembership.secret, describedSiteMembership.personal
	case TeamDomain:
		return describedTeam.md, describedTeam.secret, describedTeam.personal
	case TeamMembershipDomain:
		return describedTeamMembership.md, describedTeamMembership.secret, describedTeamMembership.personal
	case TenantDomain:
		return describedTenant.md, describedTenant.secret, describedTenant.personal
	}

	return nil, nil, nil
}

// description is what [described] answers for one entity.
type description struct {
	md               protoreflect.MessageDescriptor
	secret, personal []protoreflect.FieldDescriptor
}

func describe(m proto.Message, secret, personal []protoreflect.FieldNumber) description {
	md := m.ProtoReflect().Descriptor()
	out := description{md: md}
	for _, n := range secret {
		out.secret = append(out.secret, md.Fields().ByNumber(n))
	}
	for _, n := range personal {
		out.personal = append(out.personal, md.Fields().ByNumber(n))
	}

	return out
}

