// keptTrail is the trail a transaction has recorded and not written yet.
//
// It is kept by the transaction ([dialect.Keep]) and written by its commit,
// or a few hundred rows at a time before that, or ahead of any statement
// about the trail the transaction sends. The commit is what writes it, so
// a transaction cannot be ended with any of it left out, and one rolled
// back takes it along unwritten.
type keptTrail struct {
	// db is the client of the first write the transaction recorded, which
	// is as good as any other's: every one of them is that transaction.
	db   *ent.Client
	rows []*ent.AuditCreate

	// writing is the rows being written, by a statement that is itself
	// about the trail: asked to write them first, it finds them on the way.
	writing bool
}

// keptTrailKey is what a transaction keeps its [keptTrail] under.
type keptTrailKey struct{}

// keptTrailRows is how many rows of the trail one statement writes.
const keptTrailRows = 500

// keptTrailAbout is whether a statement is about the trail: the table's
// name as a word of it. Every statement that is about it has what is kept
// written first, so that it finds every row the transaction recorded.
var keptTrailAbout = regexp.MustCompile(`\b` + regexp.QuoteMeta(audit.Table) + `\b`).MatchString

func keptTrailOf(k *dialect.Keep, db *ent.Client) *keptTrail {
	return k.Value(keptTrailKey{}, func() any {
		v := &keptTrail{db: db}
		k.BeforeCommit(v.write)
		k.BeforeStatement(keptTrailAbout, v.write)
		return v
	}).(*keptTrail)
}

func (v *keptTrail) add(ctx context.Context, q *ent.AuditCreate) error {
	v.rows = append(v.rows, q)
	if len(v.rows) < keptTrailRows {
		return nil
	}

	return v.write(ctx)
}

// write writes what is kept, a statement for each few hundred rows.
func (v *keptTrail) write(ctx context.Context) error {
	if v.writing {
		return nil
	}
	v.writing = true
	defer func() { v.writing = false }()

	for len(v.rows) > 0 {
		n := min(len(v.rows), keptTrailRows)
		if err := v.db.Audit.CreateBulk(v.rows[:n]...).Exec(ctx); err != nil {
			return fmt.Errorf("write the trail: %w", err)
		}
		v.rows = v.rows[n:]
	}

	return nil
}

// Digests checks every live row of every kind on the trail -- every kind but
// the ones kept off it -- against the trail (payday#102, #108): each digested
// again, as a Get reads it, and compared with the digest the newest row of the trail about it
// keeps -- in the database, or in the archive `p` names once it has left. A
// row somebody changed past the servers is one that differs, and a row
// somebody added past them is one nothing on the trail is about.
//
// It changes nothing. It reads a page of a kind at a time, each page with the
// trail about it in one read-only transaction, so `db` is the database and
// not a transaction. With no archive, what is not in the database is not on
// the trail.
func Digests(ctx context.Context, db *ent.Client, d *audit1.Digest, p trail.Policy) (audit1.Rows, error) {
	var archived audit1.Archived
	if p.Archive != nil {
		n, err := p.Newest(ctx, TrailStore(db))
		if err != nil {
			return audit1.Rows{}, fmt.Errorf("the archive: %w", err)
		}
		archived = archivedDigests(n)
	}

	out := audit1.Rows{}
	if err := audit1.CheckKind(ctx, d, checkedApiKey(db), archived, &out); err != nil {
		return out, fmt.Errorf("api-key: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedBinding(db), archived, &out); err != nil {
		return out, fmt.Errorf("binding: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedConnection(db), archived, &out); err != nil {
		return out, fmt.Errorf("connection: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedContinuation(db), archived, &out); err != nil {
		return out, fmt.Errorf("continuation: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedCredential(db), archived, &out); err != nil {
		return out, fmt.Errorf("credential: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedDelegation(db), archived, &out); err != nil {
		return out, fmt.Errorf("delegation: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedEmail(db), archived, &out); err != nil {
		return out, fmt.Errorf("email: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedGroup(db), archived, &out); err != nil {
		return out, fmt.Errorf("group: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedGroupExposure(db), archived, &out); err != nil {
		return out, fmt.Errorf("group-exposure: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedGroupMembership(db), archived, &out); err != nil {
		return out, fmt.Errorf("group-membership: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedHolder(db), archived, &out); err != nil {
		return out, fmt.Errorf("holder: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedHost(db), archived, &out); err != nil {
		return out, fmt.Errorf("host: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedHostProof(db), archived, &out); err != nil {
		return out, fmt.Errorf("host-proof: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedIdentity(db), archived, &out); err != nil {
		return out, fmt.Errorf("identity: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedLink(db), archived, &out); err != nil {
		return out, fmt.Errorf("link: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedMailDomain(db), archived, &out); err != nil {
		return out, fmt.Errorf("mail-domain: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedNomination(db), archived, &out); err != nil {
		return out, fmt.Errorf("nomination: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedRole(db), archived, &out); err != nil {
		return out, fmt.Errorf("role: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedSession(db), archived, &out); err != nil {
		return out, fmt.Errorf("session: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedSite(db), archived, &out); err != nil {
		return out, fmt.Errorf("site: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedSiteMembership(db), archived, &out); err != nil {
		return out, fmt.Errorf("site-membership: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedTeam(db), archived, &out); err != nil {
		return out, fmt.Errorf("team: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedTeamMembership(db), archived, &out); err != nil {
		return out, fmt.Errorf("team-membership: %w", err)
	}
	if err := audit1.CheckKind(ctx, d, checkedTenant(db), archived, &out); err != nil {
		return out, fmt.Errorf("tenant: %w", err)
	}

	return out, nil
}

// checkedApiKey is what a check of the rows reads of the api-key kind.
func checkedApiKey(db *ent.Client) audit1.Kind {
	read := func(ctx context.Context, ps ...predicate.ApiKey) (audit1.Page, error) {
		var out audit1.Page
		err := snapshot(ctx, db, func(ctx context.Context, db *ent.Client) error {
			rows, err := liveApiKey(ctx, db, ps...)
			if err != nil {
				return err
			}

			recorded, err := newestDigests(ctx, db, rows)
			out = audit1.Page{Rows: rows, Recorded: recorded}
			return err
		})

		return out, err
	}

	return audit1.Kind{
		Domain: ApiKeyDomain,
		After: func(ctx context.Context, after pdid.Id) (audit1.Page, error) {
			return read(ctx, apikey.IdGT(uuid.UUID(after)))
		},
		Of: func(ctx context.Context, ids []pdid.Id) (audit1.Page, error) {
			return read(ctx, apikey.IdIn(uuids(ids)...))
		},
	}
}

// liveApiKey is the live rows `ps` says of the api-key kind, at most a page of
// them in identifier order, each as a Get reads it.
func liveApiKey(ctx context.Context, db *ent.Client, ps ...predicate.ApiKey) ([]audit1.Live, error) {
	q := db.ApiKey.Query().Where(append(ps, apikey.DateErasedIsNil())...)
	bare.ApiKeySelectInit(q, nil)

	vs, err := q.Order(apikey.ById()).Limit(audit1.RowsPage).All(ctx)
	if err != nil {
		return nil, err
	}

	out := make([]audit1.Live, len(vs))
	for i, v := range vs {
		out[i] = audit1.Live{Object: pdid.Id(v.Id), Row: v.Proto()}
	}

	return out, nil
}

