func (r resourceRecorder) Record(ctx context.Context, s bare.Server, c bare.Change) error {
	kind := resourceChangeKind(c.By)
	previous := c.Previous
	if kind == pdpb.ChangeKind_CHANGE_KIND_UPDATED && !r.options.Previous {
		previous = nil
	}
	image := c.Value
	if image == nil {
		image = c.Previous
	}
	if image == nil {
		return nil
	}
	switch image.ProtoReflect().Descriptor().FullName() {
	case "roster.Access", "roster.ApiKey", "roster.Audit", "roster.Binding", "roster.Connection", "roster.Continuation", "roster.Credential", "roster.Delegation", "roster.Email", "roster.Group", "roster.GroupExposure", "roster.GroupMembership", "roster.Holder", "roster.Host", "roster.HostProof", "roster.Identity", "roster.Link", "roster.MailDomain", "roster.Nomination", "roster.Role", "roster.Session", "roster.Site", "roster.SiteMembership", "roster.Team", "roster.TeamMembership", "roster.Tenant":
	default:
		return nil
	}
	k, err := pdid.From(keyBytes(c.Key))
	if err != nil {
		return err
	}
	id := pdid.New(OutboxDomain)
	at := time.Now().UTC()
	event, err := resource.Event(id[:], at, c.Method, watch.CallMethod(ctx, c.Method), kind, publicResource(previous), publicResource(c.Value))
	if err != nil {
		return err
	}
	if r.selectEvent != nil {
		ok, err := r.selectEvent(ctx, proto.Clone(event).(*pdpb.WatchEvent))
		if err != nil || !ok {
			return err
		}
	}
	doc := []byte{}
	if v := hidden(k, c.Patch); v != nil {
		doc, err = proto.Marshal(v)
		if err != nil {
			return err
		}
	}
	if r.outbox {
		data, err := proto.Marshal(event)
		if err != nil {
			return err
		}
		var actor, tenant pdid.Id
		if f, ok := frame.From(ctx); ok {
			actor = f.Actor
			tenant = f.Tenant
		}
		if err := s.Db.Outbox.Create().SetId(id.Uuid()).SetDateCreated(at).SetActorId(actor.Uuid()).SetTenantId(tenant.Uuid()).SetMethod(c.Method).SetBy(c.By).SetObjectId(k.Uuid()).SetPatch(doc).SetEvent(data).Exec(ctx); err != nil {
			return err
		}
	}
	if r.w != nil {
		r.w.Note(ctx, watch.Change{Method: c.Method, By: c.By, Key: k, Patch: doc, Resource: event})
	}
	return nil
}
